using GraphApi.Models.ANM.TiposAnuncio;namespace GraphApi.Services.ANM.TiposAnuncio{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposAnuncios.    /// </summary>    public interface ITiposAnuncioService    {        /// <summary>        /// Obtiene la lista de TiposAnuncios con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposAnuncio>> GetTiposAnuncios(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposAnuncios con filtros opcionales.        /// </summary>        /// <param name="tipoAnuncioID">Filtro opcional para TipoAnuncioID.</param>        /// <param name="tipoAnuncio">Filtro opcional para TipoAnuncio.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposAnunciosDynamic(            int? tipoAnuncioID,            string? tipoAnuncio,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposAnuncio.        /// </summary>        /// <param name="objInput">Datos para crear el TiposAnuncio.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposAnuncio> CreateTiposAnuncio(            clCreateTiposAnuncio objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposAnuncio.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposAnuncio, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposAnuncio?> UpdateTiposAnuncio(            clUpdateTiposAnuncio objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposAnuncio por su ID.        /// </summary>        /// <param name="nTiposAnuncioID">ID del TiposAnuncio a eliminar.</param>        Task<bool> DeleteTiposAnuncio(int nTiposAnuncioID);    }}